const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
function safe(root,relative){
 if(path.isAbsolute(relative)||relative.split('/').includes('..'))throw Error('Unsafe update path.');
 const full=path.join(root,relative);let current=root;
 if(fs.lstatSync(root).isSymbolicLink())throw Error('Working folder cannot be a symlink.');
 for(const part of relative.split('/')){current=path.join(current,part);if(fs.existsSync(current)&&fs.lstatSync(current).isSymbolicLink())throw Error('Symlink refused: '+relative);}
 return full;
}
function install(root,runTests=true){
 if(!fs.existsSync(root)||!fs.statSync(root).isDirectory())throw Error('AIK-Internal 6 folder not found. No change made.');
 for(const [name,hashes]of Object.entries(PACKAGE.baselines)){
  const p=safe(root,name);if(!fs.existsSync(p)||!hashes.includes(sha(fs.readFileSync(p))))throw Error('Source differs from CP004/CP005: '+name+'. Stopped without changing files.');
 }
 const changes=[];
 for(const item of PACKAGE.files){const bytes=Buffer.from(item.data,'base64');if(sha(bytes)!==item.sha)throw Error('Invalid update payload.');const p=safe(root,item.name),exists=fs.existsSync(p),old=exists?fs.readFileSync(p):null;
  if(old&&sha(old)===item.sha)continue;
  if(exists&&item.name.startsWith('Checkpoints/CP005/'))throw Error('Existing CP005 checkpoint differs: '+item.name);
  if(exists&&item.name==='bulk.test.cjs')throw Error('Existing new test differs; refusing to overwrite.');
  changes.push({item,p,bytes,old});
 }
 if(!changes.length){console.log('ALREADY_INSTALLED: CP005 files match. No files changed.');return null;}
 safe(root,'Checkpoints');fs.mkdirSync(path.join(root,'Checkpoints'),{recursive:true});
 const backup=fs.mkdtempSync(path.join(root,'Checkpoints','Before-CP005-'));
 const receipt={status:'BACKED_UP',target:root,at:new Date().toISOString(),files:changes.map(c=>({name:c.item.name,before:c.old?sha(c.old):null,after:c.item.sha}))};
 for(const c of changes)if(c.old){const p=path.join(backup,'files',c.item.name);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,c.old,{flag:'wx'});}
 const journal=path.join(backup,'UPDATE-RECEIPT.json');fs.writeFileSync(journal,JSON.stringify(receipt,null,2));
 console.log('Backup: '+backup);
 try{
  // Recheck every destination after backup and before replacing any file.
  for(const c of changes){safe(root,c.item.name);const now=fs.existsSync(c.p)?sha(fs.readFileSync(c.p)):null;if(now!==(c.old?sha(c.old):null))throw Error('File changed during backup: '+c.item.name);}
  for(const c of changes){fs.mkdirSync(path.dirname(c.p),{recursive:true});const temp=c.p+'.aik-update-'+crypto.randomBytes(8).toString('hex');fs.writeFileSync(temp,c.bytes,{flag:'wx'});fs.renameSync(temp,c.p);}
  for(const c of changes)if(sha(fs.readFileSync(c.p))!==c.item.sha)throw Error('Readback failed: '+c.item.name);
  receipt.status='SOURCE_VERIFIED';fs.writeFileSync(journal,JSON.stringify(receipt,null,2));
  if(runTests)for(const test of ['test.cjs','preview.test.cjs','planner.test.cjs','bulk.test.cjs']){const r=cp.spawnSync(process.execPath,[test],{cwd:root,encoding:'utf8'});fs.writeFileSync(path.join(backup,test+'.log'),(r.stdout||'')+(r.stderr||''));if(r.status!==0)throw Error(test+' failed; inspect its log in the backup.');}
  receipt.status=runTests?'INSTALLED_TESTS_PASS':'INSTALLED_TESTS_NOT_RUN';fs.writeFileSync(journal,JSON.stringify(receipt,null,2));
  console.log('CP005 INSTALLED in the same working folder.');if(runTests)console.log('51 local checks PASS.');
  console.log('No Beauty, Google, Nakka, Git or credential files changed.');return backup;
 }catch(e){receipt.status='INCOMPLETE_REVIEW_REQUIRED';receipt.error=e.message;fs.writeFileSync(journal,JSON.stringify(receipt,null,2));throw Error(e.message+' Backup preserved at '+backup+'. Do not start the preview until reviewed.');}
}
if(require.main===module){try{install(TARGET);}catch(e){console.error('STOP: '+e.message);process.exitCode=1;}}
module.exports={install,PACKAGE,TARGET};
